'use strict';
const D=window.COOKT, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={artworkViews:{},packFormats:{},packScene:'studio',railTheme:'green',photoView:'pov',gallery:{},productSection:'photography',scrollPositions:{},renderedRoute:null,colors:{},railScroll:0,productPage:0,productQuery:'',logo:null,logoMode:'paper',returnRoute:'#/packaging'};
try{state.colors=JSON.parse(localStorage.getItem('cookt-color-preview-v3')||'{}')}catch{}
const assetLogo=()=>state.logo||'assets/logo.png';
const launch=D.products.filter(p=>p.channel==='launch');
for(const p of launch){if(!p.colorOptions?.some(c=>c.id===state.colors[p.id]))delete state.colors[p.id];}
try{localStorage.setItem('cookt-color-preview-v3',JSON.stringify(state.colors))}catch{}
const source=id=>D.sources.find(s=>s.id===id);
const sourceLink=()=>'';
const isInternal=D.audience==='internal';
const canDownloadAI=false;
const image=p=>{if(!p.image&&p.channel==='launch')return `<span class="image-pending">Photography in revision</span>`;if(!p.image)return `<span class="no-image" aria-hidden="true">${E(p.name.split(' ').slice(0,2).map(s=>s[0]).join(''))}</span>`;const alt=E(p.name);if(p.imageCrop){const [x,y,size]=p.imageCrop;return `<span class="source-plate" style="--zoom:${1254/size*100}%;--left:${-x/size*100}%;--top:${-y/size*100}%"><img width="1254" height="1254" src="${E(p.image)}" alt="${alt}" loading="lazy"></span>`;}return `<img src="${E(p.image)}" alt="${alt}" loading="lazy">`;};
const pill=(s,c='')=>`<span class="status ${c}">${E(s)}</span>`;
const link=(href,label,cls='')=>!href||href.startsWith('#source-unavailable')?'':`<a class="${cls}" href="${E(href)}" ${href?.startsWith('http')?'target="_blank" rel="noopener"':''}>${E(label)}</a>`;
function heading(title,kicker,desc='',action=''){return `<div class="page-heading"><div>${kicker?`<div class="eyebrow">${E(kicker)}</div>`:""}<h1>${E(title)}</h1></div>${action||(desc?`<p>${E(desc)}</p>`:"")}</div>`;}
function tabbar(items,active){return `<nav class="subnav" aria-label="Section navigation">${items.map(([id,t,href])=>`<a class="${active===id?'active':''}" href="${href}" ${active===id?'aria-current="page"':''}>${E(t)}</a>`).join('')}</nav>`;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2200);}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Copied');}catch{toast('Copy unavailable in this browser');}}
function selectedColor(p){return p.colorOptions?.find(c=>c.id===state.colors[p.id])||p.colorOptions?.find(c=>c.id===p.defaultColor)||{field:p.color,ink:p.ink,name:'Current',status:p.colorStatus};}
function heatMeter(p,compact=false){if(!p.heat?.level)return '';const h=D.packaging.heatIcons;return `<span class="heat-meter ${compact?'compact':''}" role="img" aria-label="${E(p.heat.label)} · ${E(p.heat.status)}"><svg class="heat-source" viewBox="${h.viewBox}" aria-hidden="true"><path d="${h.paths[String(p.heat.level)]}" fill-rule="nonzero"/></svg>${compact?'':`<span>${E(p.heat.label)} <small>${E(p.heat.status)}</small></span>`}</span>`;}
function colorChoices(p){return `<div class="color-choices" aria-label="${E(p.name)} color options">${p.colorOptions.map(c=>`<button data-color-product="${p.id}" data-color="${c.id}" aria-pressed="${selectedColor(p).id===c.id}" title="${E(c.name)} · ${E(c.status)}"><i style="background:${c.field}"></i><span>${E(c.name)}</span>${selectedColor(p).id===c.id?'<b aria-hidden="true">✓</b>':''}</button>`).join('')}</div>`;}

function colorStyle(c){return `--field:${c.field};--ink:${c.ink};--accent:${c.accent||c.ink};--accent-ink:${c.accent?c.ink:c.field};--logo-ink:${c.logoInk||c.ink};--logo-outline:${c.logoOutline||'transparent'}`;}
function rangeColors(){return `<div class="range-palette-board">${launch.map(p=>{const c=selectedColor(p);return `<a href="#/packaging/${p.id}/color" style="background:${c.field};color:${c.ink}"><strong>${E(p.name)}</strong><span>${c.field}<i style="background:${c.ink}"></i></span></a>`;}).join('')}</div>`;}
function feedback(owner,ids=null){const rows=D.reviews.filter(r=>r.owner===owner&&(!ids||ids.includes(r.id)));return rows.length?`<section class="work-feedback" aria-label="Feedback"><div class="section-head"><h2>Feedback</h2><span class="small-label">Current round</span></div>${rows.map(r=>`<section id="feedback-${r.id}" class="feedback-row"><div><span class="small-label">${E(r.category)}</span><h3>${E(r.title)}</h3>${pill(r.status)}</div><ul class="check-list">${r.checks.map(t=>`<li>${E(t)}</li>`).join('')}</ul></section>`).join('')}</section>`:'';}

function plateStrip(){const dishes=launch.filter(p=>p.image);return `<section class="photography-strip"><div class="section-head"><h2>The launch plates</h2><div class="rail-surface" role="group" aria-label="Plate strip background">${[['green','Dark green'],['paper','Paper']].map(([id,t])=>`<button data-rail-theme="${id}" aria-pressed="${state.railTheme===id}">${t}</button>`).join('')}</div></div><div class="plate-stage ${state.railTheme==='green'?'on-green':''}"><div class="plate-rail" tabindex="0" aria-label="Launch plate strip. Use arrow keys to browse."><span class="rail-letter rail-c" aria-hidden="true"><img src="assets/logo-c.png" alt=""></span>${dishes.map(p=>`<a class="dish-slide" href="#/packaging/${p.id}/photography" data-product-origin="photography">${image(p)}<span class="dish-caption">${E(p.name)} ↗</span></a>`).join('')}<span class="rail-letter rail-kt" aria-hidden="true"><img src="assets/logo-kt.png" alt=""></span></div></div><div class="rail-tools"><span class="quiet-note">Packaging angle / full ceramic</span><div class="rail-actions"><span id="rail-position">1 / ${dishes.length}</span><button class="arrow" data-dir="-1" aria-label="Previous plate">←</button><button class="arrow" data-dir="1" aria-label="Next plate">→</button></div></div></section>`;}

function renderAsset(p,view='white'){if(D.packaging.renders?.status==='Rejected')return null;return D.packaging.renders?.products?.[p.id]?.[selectedColor(p).id]?.[view];}

function currentFront(p){return renderAsset(p,'front')||p.frontArtwork?.image;}
function productGallery(p){
 const entries=[['pack','Pack mockup',renderAsset(p)],['front','Front artwork',currentFront(p)],['plate','Food',p.image]];
 const selected=entries.find(x=>x[0]===state.gallery[p.id]&&x[2])||entries.find(x=>x[2]);
 if(!selected)return '';
 const [view,label,src]=selected;
 return `<div class="product-gallery" id="gallery-${p.id}"><button class="gallery-stage ${view==='plate'?'is-plate':''} ${view==='front'?'is-front':''}" data-zoom-src="${E(src)}" data-zoom-title="${E(p.name+' · '+label)}" aria-label="Enlarge ${E(p.name+' '+label)}"><img src="${E(src)}" alt="${E(p.name+' · '+label)}" width="1200" height="1200" loading="lazy"><span class="zoom-mark" aria-hidden="true">↗</span></button><div class="gallery-strip" role="group" aria-label="${E(p.name)} imagery">${entries.filter(x=>x[2]).map(([id,name,href])=>`<button data-gallery-product="${p.id}" data-gallery-view="${id}" aria-pressed="${id===view}"><img src="${E(href)}" alt=""><span>${name}</span></button>`).join('')}</div></div>`;
}
function retailDetails(p){return `<div class="specifications"><dl>${Object.entries(p.retail).map(([k,v])=>`<div><dt>${E(({netWeight:'Net weight',certification:'Halal',dieline:'Carton format'})[k]||k)}</dt><dd>${E(v)}</dd></div>`).join('')}</dl>${isInternal&&p.dtcReference?`<details><summary>DTC source record</summary><div class="source-record"><p>${E(p.dtcReference.match)}</p><p>${E(p.dtcReference.nutritionRecord)}</p><p class="source-alert">DTC figures; retail equivalence unconfirmed.</p>${p.dtcReference.ingredients?`<h3>Listed ingredients</h3><p>${E(p.dtcReference.ingredients)}</p>`:''}</div></details>`:''}</div>`;}
function artworkDownload(){return '';}
function sleeveDownload(panel){return artworkDownload(panel);}
function artworkViewer(p,item,format,context='pack'){
 const id=`${context}-${p.id}-${format}`,selection=state.artworkViews[id]||(state.artworkViews[id]={kind:'front',indices:{front:0,back:0,side:0}});
 const panels=item.panels||[],kind=panels.some(x=>x.kind===selection.kind)?selection.kind:'front',options=panels.filter(x=>x.kind===kind),index=Math.min(selection.indices[kind]||0,options.length-1),panel=options[index];
 if(!panel)return '';
 const optionLabel=x=>x.label.replace('Illustrated preparation / dish bullets','Preparation + dish bullets').replace('Front / light-green lettering option','Light-green lettering');
 const labels=Object.fromEntries(Object.entries({front:'Front',back:'Back',side:'Side',dieline:'Dieline'}).filter(([key])=>panels.some(x=>x.kind===key))),title=`${p.name} · ${format==='frozen'?'Frozen pack':'DTC sleeve'} · ${panel.label}`;
 const width=panel.width||(format==='frozen'?2100:1600),height=panel.height||(kind==='side'?(format==='frozen'?300:229):(format==='frozen'?1500:1143));
 return `<div class="artwork-viewer" id="viewer-${id}" data-art-viewer="${id}" data-product="${p.id}" data-format="${format}" data-context="${context}"><div class="artwork-controls"><div class="artwork-part-tabs" role="tablist" aria-label="${E(p.name)} ${format==='frozen'?'frozen pack':'DTC sleeve'} panels">${Object.entries(labels).map(([key,label])=>`<button type="button" role="tab" id="art-tab-${id}-${key}" data-art-kind="${key}" aria-selected="${kind===key}" aria-controls="art-panel-${id}" tabindex="${kind===key?0:-1}">${label}</button>`).join('')}</div><div class="artwork-option">${options.length>1?`<label for="art-option-${id}">${labels[kind]} design</label><select id="art-option-${id}" data-art-option aria-label="${E(p.name)} ${labels[kind].toLowerCase()} design">${options.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${E(optionLabel(x))}</option>`).join('')}</select>`:`<span>${E(panel.label)}</span>`}</div></div><div role="tabpanel" id="art-panel-${id}" aria-labelledby="art-tab-${id}-${kind}" tabindex="0"><figure class="artwork-sheet ${kind==='side'?'is-side':''}"><button type="button" class="artwork-enlarge" data-zoom-src="${E(panel.image)}" data-zoom-title="${E(title)}" aria-label="Enlarge ${E(title)}"><img src="${E(panel.image)}" alt="${E(title)}" width="${width}" height="${height}" loading="lazy"><span class="artwork-enlarge-label" aria-hidden="true">View detail ↗</span></button><figcaption><span>${E(panel.label)}</span><span>${panel.download?`<a class="text-link" href="${E(panel.download)}" download>Download PNG ↓</a>`:''} ${index+1} / ${options.length}</span></figcaption></figure></div></div>`;
}
function updateArtworkView(viewer,kind,index,focusTarget){
 const {product,format,context,artViewer:id}=viewer.dataset,p=launch.find(x=>x.id===product),item=(format==='frozen'?D.packaging.artwork.products:D.applicationReview.sleeves).find(x=>x.product===product);
 const current=state.artworkViews[id];if(kind)current.kind=kind;if(index!==undefined)current.indices[current.kind]=index;
 viewer.outerHTML=artworkViewer(p,item,format,context);bind();
 if(focusTarget)$(`#viewer-${id} ${focusTarget}`)?.focus({preventScroll:true});
}
function packagingPanels(p){
 const sleeve=D.applicationReview.sleeves.find(x=>x.product===p.id),frozen=D.packaging.artwork.products.find(x=>x.product===p.id),active=state.packFormats[p.id]||'frozen';
 const body=(item,format,label)=>`<div class="pack-artwork-toolbar"><p>${format==='frozen'?'The launch carton, panel by panel.':'Photography and type-only fronts, with coordinated back artwork.'}</p>${artworkDownload(item,format)?`<a class="button pack-ai-download" href="${E(artworkDownload(item,format))}" download aria-label="Download ${E(p.name+' '+label)} Illustrator artwork">Download ${label} .ai ↓</a>`:''}</div>${artworkViewer(p,item,format)}`;
 return `<section class="pack-panel-system" id="panels-${p.id}" tabindex="-1" aria-labelledby="artwork-title-${p.id}"><h3 id="artwork-title-${p.id}">Artwork</h3><div class="pack-format-tabs" role="tablist" aria-label="${E(p.name)} packaging format">${[['frozen','Frozen pack'],['sleeve','DTC sleeve']].map(([id,label])=>`<button role="tab" id="tab-${p.id}-${id}" data-pack-format="${id}" data-pack-product="${p.id}" aria-controls="artwork-${p.id}-${id}" aria-selected="${active===id}" tabindex="${active===id?0:-1}">${label}</button>`).join('')}</div>${[['frozen',frozen,'frozen pack'],['sleeve',sleeve,'DTC sleeve']].map(([id,item,label])=>`<div role="tabpanel" data-pack-format-panel="${id}" id="artwork-${p.id}-${id}" aria-labelledby="tab-${p.id}-${id}" ${active===id?'':'hidden'}>${body(item,id,label)}</div>`).join('')}<p class="pack-panel-note">Review artwork · Product information and supplier dimensions await confirmation.</p></section>`;
}
function setPackFormat(product,format,focus=false){
 state.packFormats[product]=format;const section=$('#panels-'+product);if(!section)return;
 section.querySelectorAll('[data-pack-format]').forEach(tab=>{const active=tab.dataset.packFormat===format;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});
 section.querySelectorAll('[data-pack-format-panel]').forEach(panel=>panel.hidden=panel.dataset.packFormatPanel!==format);
 if(focus)$(`#tab-${product}-${format}`).focus({preventScroll:true});
}

function packagingProduct(p,i){const c=selectedColor(p);return `<section class="pack-product" tabindex="-1" id="pack-${p.id}" data-pack-section="${p.id}" aria-labelledby="title-${p.id}"><header class="pack-product-heading"><span class="small-label">${String(i+1).padStart(2,'0')}</span><h2 id="title-${p.id}">${E(p.name)}</h2></header><div class="pack-product-layout">${productGallery(p)}<div class="pack-product-information"><p class="pack-product-summary">${E(p.summary)}</p>${heatMeter(p)}<div class="pack-palette" id="palette-${p.id}" tabindex="-1"><h3>Palette</h3><div>${[['Background',c.field],['Lettering',c.ink]].map(([name,hex])=>`<button data-copy="${hex}" aria-label="Copy ${E(p.name)} ${name.toLowerCase()} ${hex}"><i style="background:${hex}"></i><span>${name}<b>${hex}</b></span></button>`).join('')}</div>${p.colorOptions?.length>1?colorChoices(p):''}</div><details class="pack-detail" id="facts-${p.id}"><summary>Product information</summary>${retailDetails(p)}</details><details class="pack-detail" id="styling-${p.id}"><summary>Photography & styling</summary><ul class="check-list">${p.styling.map(t=>`<li>${E(t)}</li>`).join('')}</ul></details><details class="pack-detail" id="notes-${p.id}"><summary>Artwork & production</summary><ul class="check-list">${p.packNotes.map(t=>`<li>${E(t)}</li>`).join('')}</ul></details></div></div>${packagingPanels(p)}<div class="pack-product-links"><a href="#/brand/photography/food">Food & ceramic direction ↗</a></div></section>`;}
function bindProductRecord(p){const copyButton=$('#copy-record-link'),downloadButton=$('#download-record');if(copyButton)copyButton.onclick=()=>copy(location.href);if(downloadButton&&isInternal)downloadButton.onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=`cookt-${p.id}-${p.revision}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);};}
function latest(arrow){
 const L=D.hub.index.latest;if(!L?.items?.length)return '';
 const ext=x=>x.external?' target="_blank" rel="noopener"':'';
 const art=x=>x.files?`<span class="latest-art latest-files latest-files-${x.files.length}">${x.files.map(f=>`<a href="${E(f.href)}" target="_blank" rel="noopener" aria-label="Open ${E(f.title)}"><img src="${E(f.preview)}" alt="${E(f.title)}" loading="lazy"></a>`).join('')}</span>`:`<a class="latest-art" href="${E(x.href)}"${ext(x)} tabindex="-1" aria-hidden="true"><img src="${E(x.preview)}" alt="" loading="lazy"></a>`;
 return `<section class="home-latest" aria-labelledby="latest-title"><div class="directory-heading"><h2 id="latest-title">${E(L.title)}</h2><p>${E(L.intro)}</p></div><div class="latest-grid">${L.items.map((x,i)=>`<article class="latest-card latest-${E(x.size||'third')}">${art(x)}<div class="latest-meta"><span>${E(x.kind)}</span><span>${E(x.date)}</span></div><h3><a href="${E(x.href)}"${ext(x)}>${E(x.title)}<span class="latest-arrow">${arrow}</span></a></h3><p>${E(x.detail)}</p></article>`).join('')}</div></section>`;
}
function index(){
 const H=D.hub.index, arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';
 const visuals={
  brand:`<div class="portal-art portal-identity" aria-hidden="true"><span class="identity-line">${E(D.tagline).toLowerCase().replace(/^a /,'A ').replace(' on frozen','<br>on frozen')}.</span><img src="assets/logo.png" alt=""><div class="identity-colors"><i></i><i></i><i></i><i></i></div></div>`,
  packaging:`<div class="portal-art portal-packaging-photo"><img src="${E(H.packagingBeauty.image)}" alt="${E(H.packagingBeauty.alt)}" width="1536" height="1024" loading="lazy"><span class="portal-art-label">Launch range / In review</span></div>`,
  applications:`<div class="portal-art portal-applications" aria-hidden="true"><img class="portal-web" src="${E(D.applicationReview.website.find(x=>x.id==='d1').image)}" alt="" loading="lazy"><img class="portal-mobile" src="${E(D.applicationReview.website.find(x=>x.id==='d1').mobile)}" alt="" loading="lazy"><span class="portal-art-label">Website & email / In review</span></div>`,
  library:`<div class="portal-art portal-library" aria-hidden="true"><div class="asset-sheet asset-sheet-logo"><span>01 / Wordmark</span><img src="assets/logo-vertical.png" alt=""><small>PNG</small></div><div class="asset-sheet asset-sheet-photo"><span>02 / Photography</span><img src="${E(D.hub.index.libraryPhotography.image)}" alt="" loading="lazy"><small>WEBP</small></div><div class="asset-sheet asset-sheet-color"><span>03 / Color</span><div>${launch.map(p=>`<i style="background:${selectedColor(p).field}"></i>`).join('')}</div><small>Launch palette</small></div></div>`
 };
 return `<div class="hub-home home-v012">
 <header class="home-masthead"><span>Brand hub</span><button class="home-find" data-search-open aria-label="Search the brand hub"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg><span>Find something</span><kbd>⌘ K</kbd></button></header>
 <section class="welcome" aria-labelledby="welcome-title"><div class="welcome-copy"><div class="welcome-overline"><span class="welcome-dot" aria-hidden="true"></span>Welcome to COOKT</div><h1 id="welcome-title">${E(D.tagline).toLowerCase().replace(/^a /,'A ').replace(' fresh ',' fresh<br>').replace(' on frozen','<br>on frozen')}<span class="welcome-period">.</span></h1><div class="welcome-bottom"><p>${E(H.intro)}</p><button class="welcome-explore" data-home-explore>Explore the hub<span aria-hidden="true">↓</span></button></div></div><figure class="welcome-photo"><img src="${E(H.hero.image)}" alt="${E(H.hero.alt)}" width="1122" height="1402" fetchpriority="high"><figcaption><a href="#/brand/photography">Jamaican Rasta Chicken Pasta<span>Photography study ${arrow}</span></a></figcaption></figure></section>
 ${latest(arrow)}
 <section class="hub-directory" aria-labelledby="directory-title"><div class="directory-heading"><h2 id="directory-title" tabindex="-1">${E(H.directoryTitle)}</h2><p>${E(H.directoryIntro)}</p></div><nav class="portal-grid" aria-label="Explore the brand">${H.destinations.map((d,i)=>`<article class="portal portal-${d.id}"><a class="portal-main" href="${E(d.href)}" aria-labelledby="portal-title-${d.id}">${visuals[d.id]}<div class="portal-heading"><span class="portal-number">0${i+1}</span><h3 id="portal-title-${d.id}">${E(d.title)}</h3><span class="portal-arrow">${arrow}</span></div><p>${E(d.description)}</p></a><nav class="portal-links" aria-label="${E(d.title)} shortcuts">${d.links.map(l=>link(l.href,l.title)).join('')}</nav></article>`).join('')}</nav></section>
 <section class="home-toolbox" aria-labelledby="toolbox-title"><div><span class="home-kicker">${E(H.shortcutKicker)}</span><h2 id="toolbox-title">${E(H.shortcutTitle)}</h2></div><div class="home-toolbox-links">${H.shortcuts.map(s=>`<a href="${E(s.href)}"><span><strong>${E(s.title)}</strong><small>${E(s.detail)}</small></span>${arrow}</a>`).join('')}</div></section>
 <section class="home-progress" aria-labelledby="progress-title"><div><span class="home-kicker">In development</span><h2 id="progress-title">Current work.</h2><p>Current work and the next decisions.</p></div><div class="home-progress-list">${D.reviews.map(r=>`<a href="${E(r.href)}"><strong>${E(r.title)}</strong><span>${E(r.status)}</span>${arrow}</a>`).join('')}</div></section>
 </div>`;
}
function bindHome(){
 const explore=$('[data-home-explore]');
 if(explore)explore.onclick=()=>{const target=$('#directory-title');target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});};
}

function guidelineVisual(i){
 if(i===0)return '<img src="assets/logo.png" alt="COOKT identity">';
 if(i===1)return `<img src="${E(currentFront(launch[0]))}" alt="Jamaican Rasta Chicken Pasta front panel">`;
 if(i===2)return `<div class="guideline-color-bars">${launch.map(p=>`<i style="background:${selectedColor(p).field}"></i>`).join('')}</div>`;
 if(i===3)return `<img src="${E(launch[1].image)}" alt="Creamy Blackened Chicken Pasta plate">`;
 if(i===4)return '<img src="assets/international-specimen.png" alt="International type specimen">';
 return `<strong>${E(D.tagline)}</strong>`;
}
function brand(part='platform'){const parts=['platform','logo','colors','type','photography','guidelines'];if(!parts.includes(part))part='platform';let body='';if(part==='platform'){body=renderBrandOverview();}else if(part==='logo'){body=`<div class="logo-controls"><div class="tabs" aria-label="Logo background">${['paper','forest','paprika'].map(x=>`<button data-logo-mode="${x}" class="${state.logoMode===x?'active':''}" aria-pressed="${state.logoMode===x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="button-group"><label class="button" for="logo-file">Try a logo ↥</label><input type="file" accept="image/svg+xml,image/png,image/jpeg,image/webp" id="logo-file" hidden><button class="button" id="logo-reset">Reset</button></div></div><div class="logo-proof ${state.logoMode}"><img class="preview-logo" src="${assetLogo()}" alt="COOKT D1 logo preview"></div><div class="inspector-caption"><span id="logo-preview-status">${state.logo?'Local preview only':'D1 wordmark'}</span>${pill('C refinement in review')}</div><div class="two-column ruled logo-visual-points"><div><div class="logo-point-art logo-point-horizontal"><img src="assets/logo-vertical.png" alt="Vertical D1 wordmark on deep green"></div><h3>Vertical signature</h3><p>Scale the exact D1 wordmark to the full pack height with equal top and bottom margins. Keep the halal mark separate.</p><a class="text-link" href="#/packaging/system">See the current pack composition ↗</a></div><div><div class="logo-point-art logo-point-comparison"><img src="assets/logo-c.png" alt="C detail from the current D1 wordmark"></div><h3>C detail</h3><p>Legibility is under review at pack scale.</p></div></div><div class="download-row">${link('assets/logo.png','Horizontal PNG ↓','button')}${link('assets/logo-vertical.png','Vertical PNG ↓','button')}${D.audience==='public'?'':link('#source-unavailable','Logo PDF ↓','button')}</div>`; }else if(part==='colors'){body=`<div class="brand-base"><div><h2>Paper. Ink. Deep green.</h2></div><div class="base-chips"><span style="background:#F7F7F2;color:#18241E">Paper</span><span style="background:#18241E;color:#F7F7F2">Ink</span><span style="background:#103E2C;color:#F5EDD9">Deep green</span></div></div><div class="brand-color-principles"><section><div class="color-principle-art color-principle-range">${launch.map(p=>`<span style="background:${selectedColor(p).field}"><img src="${E(p.image)}" alt="${E(p.name)}"></span>`).join('')}</div><h3>Four dishes, four palettes.</h3><p>Yellow belongs to Lemon Chicken Orzo and selected accents.</p></section></div><div class="brand-range-link"><div class="section-head"><h2>Product palettes</h2><a href="#/packaging/palette">Explore the range ↗</a></div>${rangeColors()}</div>`;}else if(part==='type'){body=renderSystemStudies();}else if(part==='photography'){body=photographyView();}else{body=`<div class="guidelines-head"><div><h2>Brand guidelines</h2></div>${pill('In development')}</div><div class="guideline-grid">${[['Identity','D1 selected','Latin-only signature. Halal stays separate. C refinement pending.'],['Composition','Selected','Full-height vertical signature, equal top and bottom margins, close bowl crop and complete meal names.'],['Color','In development','Distinct product colors. Confirm after tasting and print proofs.'],['Photography','Working guide','Choose shots by purpose. Follow the food, lifestyle, color, framing and delivery guidance. Final product shoot pending.'],['Type','Working','Simple sans for the hub. Pack typography awaits its final specification.'],['Copy','Current line',D.tagline+'. Retail claims require product-specific evidence.']].map(([title,status,body],i)=>`<section><div class="guideline-art guideline-art-${i}">${guidelineVisual(i)}</div><div class="section-head"><h3>${title}</h3>${pill(status)}</div><p>${body}</p></section>`).join('')}</div><div class="pg-next"><a href="#/brand/photography">Open the complete photography guide ↗</a></div><div class="version-row"><span>v${D.version} / ${E(D.updated)}</span><a href="#/library">Documents ↗</a></div>`;}if(part==='logo')body=renderLogoVersions()+body;if(part==='colors')body+='<div class="pg-next"><a href="#/brand/photography/color">Photography color pairings & set styling ↗</a></div>';return `<div class="page ${part==='platform'?'brand-overview-page':''}">${heading('Brand','','')}${tabbar([['platform','Overview','#/brand'],['logo','Logo','#/brand/logo'],['colors','Color','#/brand/colors'],['type','Typography','#/brand/type'],['photography','Photography','#/brand/photography'],['guidelines','Guidelines','#/brand/guidelines']],part)}${body}${part==='logo'?feedback('brand',['logo-c']):part==='photography'?feedback('brand',['photography']):''}</div>`;}
function photographyView(){return state.photoView==='strip'?plateStrip():renderPhotographyGuide(state.photoView);}


function dtcSiteFacts(p){
 const ref=p.siteInfo||{},raw=ref.nutritionRecord||'';
 const keys=[['Calories','calories',' kcal'],['Protein','protein','g'],['Carbohydrates','carbohydrates','g'],['Fat','fat','g']];
 const header=raw.match(/Per Serving\s*[–-]\s*(\d+)\s*kcal/i);
 const facts=keys.map(([label,key,unit])=>{const m=raw.match(new RegExp('\\b'+label+':\\s*(\\d+)\\s*'+(key==='calories'?'':'g')+'(?=\\s+(?:Protein|Carbohydrates|Fat):|$)','i'));if(!m||(key==='calories'&&header&&header[1]!==m[1]))return '';return `<span><b>${E(m[1])}${unit}</b><small>${label}</small></span>`;}).filter(Boolean);
 return facts.length?`<div class="dtc-facts">${facts.join('')}</div>`:'';
}
function dtcTable(){
 const list=D.products.filter(p=>p.channel==='dtc'&&p.name.toLowerCase().includes(state.productQuery.toLowerCase()));
 if($('#dtc-count'))$('#dtc-count').textContent=`${list.length} of ${D.products.filter(p=>p.channel==='dtc').length} dishes`;
 if($('#dtc-clear'))$('#dtc-clear').hidden=!state.productQuery;
 $('#dtc-table').innerHTML=`<div class="dtc-catalog">${list.length?list.map(p=>`<article class="dtc-catalog-card" id="dish-${E(p.id)}"><div class="dtc-catalog-image" style="--dish-field:${E(p.color||'#E7E9E1')}">${p.image?image(p):`<span class="dtc-image-pending">Plate art in development</span>`}</div><div class="dtc-catalog-copy"><div class="dtc-catalog-top"><span class="small-label">DTC dish</span><span class="small-label">${E(p.status)}</span></div><h3>${E(p.name)}</h3>${p.summary?`<p class="dtc-summary">${E(p.summary)}</p>`:''}${dtcSiteFacts(p)}<div class="dtc-catalog-foot">${p.siteInfo?.price?`<span>Site listing: $${E(p.siteInfo.price)} <small>Observed ${E(p.siteInfo.observed)}</small></span>`:''}</div></div></article>`).join(''):'<p class="empty">No dishes match.</p>'}</div><p class="dtc-catalog-note">Product listings and nutrition are DTC source references. Availability and details can change; these are not approved retail pack claims. <a href="https://getcookt.com/collections/all" target="_blank" rel="noopener">Browse the current COOKT catalog ↗</a></p>`;
}
function productDetail(p){return `<div class="product-detail-hero" style="--field:${selectedColor(p).field};--ink:${selectedColor(p).ink}"><div class="detail-food">${image(p)}</div><div><span class="eyebrow">${p.channel==='launch'?'Retail launch':'DTC dish'} / ${E(p.revision)}</span><h2 id="detail-title">${E(p.name)}</h2>${p.summary?`<p>${E(p.summary)}</p>`:''}${heatMeter(p)}${pill(p.imageStatus)}</div></div><div class="product-detail-body">${p.channel==='launch'?`<div class="detail-section"><h3>Flavor & color</h3><p>${E(p.flavor)} ${E(p.colorNote)}</p></div><dl class="facts-grid">${Object.entries(p.retail).map(([k,v])=>`<div><dt>${E(({netWeight:'Net weight',certification:'Halal',dieline:'Pack format'})[k]||k)}</dt><dd>${E(v)}</dd></div>`).join('')}</dl>`:''}${isInternal&&p.video?`<details><summary>Product source details</summary><div class="source-record"><p>${E(p.note)}</p>${p.videoNutrition!=='Not stated'?`<div class="macro-line">${E(p.videoNutrition)}<small>Source figures · DTC only</small></div>`:''}${p.nutritionConflict?`<p class="source-alert">${E(p.nutritionConflict)} Reconcile before reuse.</p>`:''}</div></details>`:''}${isInternal&&p.dtcReference?`<details><summary>DTC source record</summary><div class="source-record">${p.dtcReference.match?`<p>${E(p.dtcReference.match)}</p>`:''}<p>${E(p.dtcReference.nutritionRecord)}</p><p class="source-alert">Source figures may conflict. These are not approved retail claims.</p>${p.dtcReference.ingredients?`<h3>Listed ingredients</h3><p>${E(p.dtcReference.ingredients)}</p>`:''}<span class="source-note">Observed ${E(p.dtcReference.observed)}</span></div></details>`:''}<div class="download-row">${isInternal&&p.sourceUrl?link(p.sourceUrl,'Product source ↗','button'):''}<button class="button" id="copy-record-link">Copy link</button>${isInternal?'<button class="button" id="download-record">Download record ↓</button>':''}</div></div>`;}
function lastRound(){return `<div class="pack-previous"><span class="public-source-preview"><img src="assets/r2-packaging-hero.webp" alt="D1 launch lineup presented in Round 02" loading="lazy"></span><div><span class="small-label">Last presented</span><h2>Round 02</h2><p>Earlier composition reference. The current full-height signature, colors, names and heat ratings supersede this artwork.</p>${link('#source-unavailable','Open presentation ↗','text-link')}</div></div>`;}
