function library(part='sources'){
 if(D.audience==='public')part='assets';
 let body;
 if(part==='assets')body=`<div class="library-grid">${D.assets.filter(a=>a.href||a.id==='font-international').map(a=>`<article class="library-item" id="asset-${E(a.id)}">${a.href?`<a class="library-preview ${a.type==='Logo'?'logo-asset':''}" href="${E(a.href)}" aria-label="Open ${E(a.title)}">${a.preview?`<img src="${E(a.preview)}" alt="${E(a.title)} preview" loading="lazy">`:a.type==='Logo'?`<img src="${E(a.href)}" alt="${E(a.title)}">`:`<span>${E(a.title)}</span>`}</a>`:`<div class="library-preview type-preview"><img src="${E(a.preview)}" alt="${E(a.title)} preview"></div>`}<div class="library-item-heading"><h2>${E(a.title)}</h2>${a.href?link(a.href,'↗'):''}</div><div class="library-meta"><span>${E(a.type)}</span><span>${E(a.status)}</span></div></article>`).join('')}</div>`;
 else body=`<div class="library-grid library-documents">${D.sources.filter(x=>(isInternal||['R2','STRATEGY','AMERICAN','PACK-COPY'].includes(x.id))&&!x.id.startsWith('DTC-')&&x.id!=='VIDEO'&&x.id!=='SLIDES').map(x=>`<article class="library-item"><a href="${E(x.href)}" class="library-preview document-preview" target="_blank" rel="noopener" aria-label="Open ${E(x.title)}">${x.preview?`<img src="${E(x.preview)}" alt="${E(x.title)} document preview" loading="lazy">`:`<span>${E(x.title)}</span>`}</a><div class="library-item-heading"><h2>${link(x.href,x.title)}</h2>${link(x.href,'↗')}</div><div class="library-meta"><span>${E(x.kind)}</span><span>${E(x.status)}</span></div>${x.id==='R2'?`<div class="document-formats">${link(x.href,'PDF ↗','text-link')}${sourceLink('SLIDES','Google Slides ↗')}</div>`:''}</article>`).join('')}</div>`;
 return `<div class="page">${heading('Library','', '')}${tabbar([['assets','Assets','#/library/assets']],part)}${body}</div>`;
}
function operations(){if(D.audience!=='internal')return notFound();return `<div class="page">${heading('Project desk.','Internal / '+D.version,'Local working records. Excluded from client exports.')}<div class="stat-grid">${[['9,493','Archived paths'],['2,550','Duplicate copies removed'],['3.91 GB','Logical space recovered']].map(x=>`<section><strong>${x[0]}</strong><span>${x[1]}</span></section>`).join('')}</div><div class="source-list">${D.internal.documents.map(d=>`<a class="source-card" href="${d.href}"><span class="eyebrow">Internal</span><h3>${E(d.title)}</h3><p>${E(d.note)}</p><div><span>Open record</span><span>↗</span></div></a>`).join('')}</div><div class="decision-callout">Client output contains selected records only. Local notes and source transcripts are not shipped.</div></div>`;}
